import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for MBConv block
mbconv_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mbconv_kernel(const float* input, float* output, int in_channels, int out_channels, int hidden_dim, int stride, int expand_ratio, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int h = idx / width;
    int w = idx % width;
    if (h < height && w < width) {
        for (int c = 0; c < out_channels; ++c) {
            float sum = 0.0f;
            for (int k = 0; k < in_channels; ++k) {
                sum += input[k * height * width + h * width + w] * 1.0f; // Simplified for demonstration
            }
            output[c * height * width + h * width + w] = sum;
        }
    }
}

torch::Tensor mbconv_cuda(torch::Tensor input, int in_channels, int out_channels, int hidden_dim, int stride, int expand_ratio) {
    int height = input.size(2);
    int width = input.size(3);
    auto output = torch::zeros({input.size(0), out_channels, height, width}, input.options());

    const int block_size = 256;
    const int num_blocks = (height * width + block_size - 1) / block_size;

    mbconv_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), in_channels, out_channels, hidden_dim, stride, expand_ratio, height, width);

    return output;
}
"""

mbconv_cpp_source = (
    "torch::Tensor mbconv_cuda(torch::Tensor input, int in_channels, int out_channels, int hidden_dim, int stride, int expand_ratio);"
)

# Compile the inline CUDA code for MBConv block
mbconv = load_inline(
    name="mbconv",
    cpp_sources=mbconv_cpp_source,
    cuda_sources=mbconv_source,
    functions=["mbconv_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()

        # Initial convolutional layer
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)

        # MBConv blocks
        self.mbconv1 = self._make_mbconv_block(32, 16, 1, 1)
        self.mbconv2 = self._make_mbconv_block(16, 24, 2, 6)
        self.mbconv3 = self._make_mbconv_block(24, 40, 2, 6)
        self.mbconv4 = self._make_mbconv_block(40, 80, 2, 6)
        self.mbconv5 = self._make_mbconv_block(80, 112, 1, 6)
        self.mbconv6 = self._make_mbconv_block(112, 192, 2, 6)
        self.mbconv7 = self._make_mbconv_block(192, 320, 1, 6)

        # Final convolutional layer
        self.conv2 = nn.Conv2d(320, 1280, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn2 = nn.BatchNorm2d(1280)

        # Fully connected layer
        self.fc = nn.Linear(1280, num_classes)

    def _make_mbconv_block(self, in_channels, out_channels, stride, expand_ratio):
        hidden_dim = round(in_channels * expand_ratio)
        return nn.Sequential(
            nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False),
            nn.BatchNorm2d(hidden_dim),
            nn.ReLU6(inplace=True),
            nn.Conv2d(hidden_dim, hidden_dim, kernel_size=3, stride=stride, padding=1, groups=hidden_dim, bias=False),
            nn.BatchNorm2d(hidden_dim),
            nn.ReLU6(inplace=True),
            nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
            nn.BatchNorm2d(out_channels),
        )

    def forward(self, x):
        x = F.relu(self.bn1(self.conv1(x)))

        x = self.mbconv1(x)
        x = self.mbconv2(x)
        x = self.mbconv3(x)
        x = self.mbconv4(x)
        x = self.mbconv5(x)
        x = self.mbconv6(x)
        x = self.mbconv7(x)

        x = F.relu(self.bn2(self.conv2(x)))
        x = F.adaptive_avg_pool2d(x, (1, 1))
        x = torch.flatten(x, 1)
        x = self.fc(x)

        return x
